import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 16 章 团队协作：从个人到 AI 团队（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第16章 团队协作：从个人到 AI 团队（易懂版）.md","filePath":"easy/第16章 团队协作：从个人到 AI 团队（易懂版）.md"}'),s={name:"easy/第16章 团队协作：从个人到 AI 团队（易懂版）.md"};function n(l,t,i,h,u,d){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-16-章-团队协作-从个人到-ai-团队-易懂版" tabindex="-1">第 16 章 团队协作：从个人到 AI 团队（易懂版） <a class="header-anchor" href="#第-16-章-团队协作-从个人到-ai-团队-易懂版" aria-label="Permalink to &quot;第 16 章 团队协作：从个人到 AI 团队（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 16 章 团队协作：从个人到 AI 团队（完整版）](../../bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 16 章 团队协作：从个人到 AI 团队.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>从&quot;我一个人用 AI&quot;到&quot;我当项目经理带 AI 团队&quot;——怎么把任务拆给多个 AI 分工干。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>一个人搬砖搬不动，就雇几个人，但<strong>得有个人分工</strong>：谁搬、谁砌、谁监工。这个人不用力气最大，但要<strong>看得清全局</strong>。</p><p>AI 协作也一样：<strong>你不一定亲自干每步，但你要当好&quot;项目经理&quot;。</strong></p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>你当项目经理，不当打字员</strong>：你的活是定目标、拆任务、验收结果，不是替 AI 写每一行。</li><li><strong>拆任务有讲究</strong>：大任务切成互不依赖的小块才能并行——&quot;先写文案再配图&quot;不能并行，&quot;A 写文案、B 画图&quot;可以。</li><li><strong>协调靠中间人</strong>：多个 AI 之间要有人（组长/我）传话、对齐口径，否则各干各的会打架。</li></ol><h2 id="任务拆分的口诀" tabindex="-1">任务拆分的口诀 <a class="header-anchor" href="#任务拆分的口诀" aria-label="Permalink to &quot;任务拆分的口诀&quot;">​</a></h2><blockquote><p><strong>能不能并行？</strong> 能 → 分给多个成员同时干； <strong>有没有先后？</strong> 有 → 排成流水线，前一步做完再下一步； <strong>谁负责收尾？</strong> 组长 → 汇总、检查、交付给你。</p></blockquote><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;做个产品宣传：A 写文案，B 设计配图思路，C 检查错别字和口径，最后汇总成一份宣传方案。&quot;</p><p><strong>你会看到</strong>：我建团队 → A/B/C 分工干活 → 我汇总 → 你验收。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 把团队当个人用——<strong>让成员各干各的，别都找你</strong>；</li><li>❌ 任务拆不干净——<strong>两块任务互相纠缠，并行就变串行</strong>；</li><li>❌ 没人管口径——<strong>两版文案说法不一致，最后全返工</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>AI 团队协作 = 你定目标拆任务 + 能并行的并行 + 组长协调汇总 + 你验收。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>下一个大任务，先问：<strong>&quot;能切成几块？哪几块能同时干？&quot;</strong> 想清楚了，再考虑组队。</p><p>👉 [下一章：打造 Skill，把方法论做成按钮（易懂版）](第17章 打造 Skill：将方法论蒸馏为可执行 Skill（易懂版）.md)</p>',20)])])}const g=o(s,[["render",n]]);export{c as __pageData,g as default};
